def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Handle edge case: empty input
    if not classes:
        return []

    # Handle edge case: single element input
    if len(classes) == 1:
        return classes

    # Handle edge case: input with duplicates
    if len(set(classes)) != len(classes):
        raise ValueError("Input contains duplicates")

    # Algorithm: sort classes by number of ancestors, then by name
    # This ensures that we prefer classes with more ancestors when there are ties
    classes.sort(key=lambda c: len(c.mro()[1:]), reverse=True)
    classes.sort()

    # Remove redundant classes
    i = 0
    while i < len(classes) - 1:
        if issubclass(classes[i], classes[i+1]):
            classes.pop(i)
        else:
            i += 1

    return classes

