def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Check if commands is a list or a string
    if isinstance(commands, str):
        commands = [commands]
    # Check if args is a list or a string
    if isinstance(args, str):
        args = [args]
    # Check if cwd is a string
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string")
    # Check if env is a dict or a string
    if env is not None and not isinstance(env, dict) and not isinstance(env, str):
        raise TypeError("env must be a dict or a string")
    # Create a list of all arguments
    all_args = []
    for command in commands:
        all_args.extend(args)
    # Check if any of the commands are empty
    if any(not command for command in commands):
        raise ValueError("One or more commands are empty")
    # Check if any of the args are empty
    if any(not arg for arg in all_args):
        raise ValueError("One or more arguments are empty")
    # Convert env to a dict if it's a string
    if isinstance(env, str):
        env = dict(env)
    # Create a new process
    process = subprocess.Popen(commands, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=env)
    # Wait for the process to finish
    stdout, stderr = process.communicate()
    # Check if the process failed
    if process.returncode != 0:
        raise subprocess.CalledProcessError(process.returncode, commands)
