def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Check if an explicit metaclass is provided
    if explicit_mc is not None:
        # If so, use it as the metaclass
        return explicit_mc

    # Otherwise, determine the metaclass from the bases
    metaclasses = set(type(base) for base in bases)

    # Check if there are any metaclasses in common
    common_metaclasses = set.intersection(*metaclasses)
    if len(common_metaclasses) == 1:
        # If so, use the most derived one
        return max(common_metaclasses, key=lambda m: len(m.__mro__))

    # Otherwise, use the most derived base class as the metaclass
    return max(bases, key=lambda base: len(base.__mro__))

