    """Generates a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url or not isinstance(url, str):
        raise ValueError("Invalid URL")

    if not document_path:
        document_path = "/.well-known/nodeinfo"

    url_parts = urlparse(url)
    if not url_parts.scheme or not url_parts.netloc:
        raise ValueError("Invalid URL")

    base_url = f"{url_parts.scheme}://{url_parts.netloc}"
    document_url = f"{base_url}{document_path}"

    resp = requests.get(url=document_url)
    if not resp.ok:
        raise ConnectionError("Failed to retrieve NodeInfo document")

    try:
        data = resp.json()
    except ValueError:
        raise ValueError("Invalid JSON response")

    if not data.get("version"):
