        AnsibleConfigManager: An instance of AnsibleConfigManager.
    """
    try:
        from ansible.config.manager import AnsibleConfigManager
        return AnsibleConfigManager()
    except ImportError:
        raise Exception("Ansible is not installed or configured properly.")

def plugins_manager(cls):
    """Gets the plugin manager. """
    try:
        return cls._plugin_manager
    except:
        raise ValueError("No plugin manager found.")

def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        return None

    try:
        spec_dict = yaml.safe_load(spec_content)
    except yaml.YAMLException as e:
        raise IRValidatorException("Invalid YAML content: {}".format(e))

    # Validate required fields in spec
    req_fields = cls.get_required_fields()
    missing_fields = []
    for field in req_fields:
        if not spec_dict.get(field):
            missing_fields.append(field)

    if missing_fields:
        raise IRValidatorException("Missing required fields in spec: {}".format(", ".join(missing_fields)))

    return spec_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. 

    Raises:
        ValueError: If the include directive is not a valid dict.
    """
    # Initialize an empty list to store the included groups
    included_groups = []

    # Iterate over the parser_dict
    for key, value in parser_dict.items():
        # If the value is a dict, it may contain an include directive
        if isinstance(value, dict):
            # If the dict has an "include" key, it is an include directive
            if "include" in value:
                # Get the include path and ensure it is a string
                include_path = value["include"]
                if not isinstance(include_path, str):
                    raise ValueError(f"Include path must be a string, but got {type(include_path)}")

                # Try to open the include file and parse it as a JSON
                try:
                    with open(include_path, "r") as f:
                        included_groups.extend(_include_groups(self, json.load(f)))
                except Exception as e:
                    raise ValueError(f"Failed to include groups from {include_path}: {e}")

        # If the value is a string, it may be a group reference
        elif isinstance(value, str):
            # If the value starts with an underscore, it is a group reference
            if value.startswith("_"):
                # Get the group name and remove the underscore
                group_name = value[1:]

                # If the group name is not in the parser_dict, it is a reference to another file
                if group_name not in parser_dict:
                    # Try to open the group file and parse it as a JSON
                    try:
                        with open(group_name, "r") as f:
                            included_groups.extend(_include_groups(self, json.load(f)))
                    except Exception as e:
                        raise ValueError(f"Failed to include groups from {group_name}: {e}")

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """

    args = []

    # Get the function arguments
    for arg in inspect.getfullargs(self):
        args.append(arg)

    # Resolve the function keyword arguments
    for kwarg in inspect.getkwonlyargs(self):
        args.append(kwarg)

    # Resolve the function default argument values
    for arg in inspect.getargspec(self):
        if arg.default is not None:
            args.append(arg.default)

    return args

def get_deprecated_args(self):
    result = {}
    for key, value in self.settings.items():
        if "deprecated" in value.lower():
            result[key] = value
    return result

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not command_name:
        raise ValueError("Command name is required")
    if not argument_name:
        raise ValueError("Argument name is required")
    if not self.commands[command_name]:
        raise KeyError("Command not found")
    if not self.commands[command_name].arguments[argument_name]:
        raise KeyError("Argument not found")
    return self.commands[command_name].arguments[argument_name].spec

def get_silent_args(self, args):
    # check if args is a list
    if not isinstance(args, list):
        raise TypeError("args must be a list")

    # initialize empty list to store silent argument names
    silent_args = []

    # iterate over args
    for arg in args:
        # check if arg is a string
        if not isinstance(arg, str):
            raise ValueError("args must contain only string values")

        # check if arg is a silent argument
        if arg.startswith("-"):
            silent_args.append(arg)

    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not all(arg in args for arg in args):
        raise ValueError("Missing required argument(s): {}".format(", ".join(args)))
    return True

def create_complex_argument_type(self, subcommand, type_name, option_name, spec_option):
    try:
        # Get the complex type class
        type_class = self.get_complex_type_class(type_name)

        # Create a new instance of the complex type
        instance = type_class()

        # Set the subcommand and option name
        instance.subcommand = subcommand
        instance.option_name = option_name

        # Set the spec option (if any)
        if spec_option:
            instance.spec_option = spec_option

        return instance
    except Exception as e:
        raise e

def get_complex_type_class(self, type_name):
    try:
        return self.ComplexTypes[type_name]
    except KeyError:
        raise ValueError("Invalid complex type name: {}".format(type_name))

def get_nested_custom_and_control_args(args):
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith("control_"):
            control_args[arg] = args[arg]
        elif arg.startswith("nested_"):
            nested_args[arg] = args[arg]
        else:
            custom_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend `vars_dict` with `extra-vars`

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    for key, value in vars_dict.items():
        if key in extra_vars:
            vars_dict[key] = value + " + " + extra_vars[key]

    return vars_dict

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    try:
        ansible_command = ['ansible-playbook', *cli_args, '-e', vars_dict]
        if ir_workspace:
            ansible_command.extend(['-i', ir_workspace.inventory_file])
        if ir_plugin:
            ansible_command.extend(['-e', ir_plugin.extra_vars])
        process = subprocess.Popen(ansible_command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            raise RuntimeError(f'Ansible failed with error code {process.returncode}: {stdout.decode()}, {stderr.decode()}')
        return stdout.decode()
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f'Ansible failed with error code {process.returncode}: {e.stdout.decode()}, {e.stderr.decode()}')
    except ValueError as e:
        raise RuntimeError(f'Invalid value provided for Ansible command: {e}')

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Step 1: Load the plugin spec file
    spec_file = os.path.join(plugin_dir, 'plugin.spec')
    with open(spec_file, 'r') as f:
        spec = json.load(f)

    # Step 2: Flatten the spec dict
    flat_dict = {}
    for key, value in spec.items():
        if isinstance(value, dict):
            flat_dict.update(value)

    # Step 3: Handle nested properties
    for key, value in flat_dict.items():
        if isinstance(value, list):
            flat_dict[key] = value[-1]

    return flat_dict

def inject_config(self):
    if not os.environ.get("CONFIG_PATH"):
        config_path = os.path.join(os.path.dirname(__file__), "config.ini")
        os.environ["CONFIG_PATH"] = config_path

def get_config(self):
    config_path = os.environ.get("CONFIG_PATH")
    if not config_path:
        raise ValueError("CONFIG_PATH environment variable is not set")
    with open(config_path) as f:
        return json.load(f)

def set_config(self, config):
    config_path = os.environ.get("CONFIG_PATH")
    if not config_path:
        raise ValueError("CONFIG_PATH environment variable is not set")
    with open(config_path, "w") as f:
        json.dump(config, f)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Path and root must be strings")
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
